User.findOneAndUpdate(
    updateQuery,
    [
      {
        $set: {
          "profileSubscription.passTier": usage.tier,
          "profileSubscription.maxCoveredCoin": coveredCoinLimit,
          "profileSubscription.freeLimit": coveredCoinLimit,
          "profileSubscription.passLimit": coveredCoinLimit,
          "profileSubscription.updatedAt": now,
          // 월 누적 한도 가산. 이미 도는 파이프라인 안에서 함께 증가시키므로 쓰기가 늘지 않고,
          // 통과와 가산이 한 번의 원자적 write 로 묶인다. 사이클 키가 다르면(=새 이용권)
          // 이번 건 가격부터 다시 센다. premiumUseCycleKey 는 상담 포함횟수와 공유하는 필드라
          // 아래 familyQuota 블록과 같은 값을 쓴다(리셋 트리거가 동일).
          ...(monthlyQuota.applies ? {
            "profileSubscription.premiumUseCycleKey": monthlyQuota.cycleKey,
            "profileSubscription.monthlySpendCoin": {
              $cond: [
                { $eq: [{ $ifNull: ["$profileSubscription.premiumUseCycleKey", ""] }, monthlyQuota.cycleKey] },
                { $add: [{ $ifNull: ["$profileSubscription.monthlySpendCoin", 0] }, coinCost] },
                coinCost,
              ],
            },
            // 재구매로 쌓인 한도(profile-limits.js resolveMonthlyPassLimitCoin)는 사이클 키와 한 쌍이다.
            // 키를 이번 사이클로 끌어오는 분기에서는 함께 0(=등급 기본값)으로 되돌린다 — 안 그러면
            // 이전 사이클의 한도가 키만 맞춰진 채 되살아난다.
            "profileSubscription.monthlyLimitCoin": {
              $cond: [
                { $eq: [{ $ifNull: ["$profileSubscription.premiumUseCycleKey", ""] }, monthlyQuota.cycleKey] },
                { $ifNull: ["$profileSubscription.monthlyLimitCoin", 0] },
                0,
              ],
            },
          } : {}),
          // 프리미엄 상담 포함 횟수(family 10회 · vvip 3회) 차감. 이미 도는 파이프라인 안에서
          // 함께 증가시키므로 쓰기가 늘지 않고, 통과와 차감이 한 번의 원자적 write 로 묶인다.
          // 사이클 키가 다르면(=새 이용권) 1부터 다시 센다.
          ...(familyQuota.applies ? {
            "profileSubscription.premiumUseCycleKey": familyQuota.cycleKey,
            "profileSubscription.premiumUseCount": {
              $cond: [
                { $eq: [{ $ifNull: ["$profileSubscription.premiumUseCycleKey", ""] }, familyQuota.cycleKey] },
                { $add: [{ $ifNull: ["$profileSubscription.premiumUseCount", 0] }, 1] },
                1,
              ],
            },
          } : {}),
          // 파이프라인 업데이트라 $push/$slice 연산자를 못 쓴다 → 집계 표현식으로 append + 상한.
          // $setUnion이 아니라 $concatArrays인 이유: $setUnion은 집합 연산이라 순서를 보장하지 않아
          // $slice(-N)과 조합하면 '최근 N개'가 아니라 '정렬 후 뒤 N개'가 남아 마커 의미가 붕괴한다.
          // 중복은 위 updateQuery의 `$ne: idempotencyMarker` 가드가 막는다(마커가 있으면 문서 자체가
          // 매치되지 않아 write가 일어나지 않음) — $setUnion의 dedup은 애초에 불필요한 이중장치였다.
          ...(idempotencyMarker ? {
            recentConsumeRequestIds: {
              $slice: [
                {
                  $concatArrays: [
                    { $ifNull: ["$recentConsumeRequestIds", []] },
                    [idempotencyMarker],
                  ],
                },
                -RECENT_CONSUME_REQUEST_ID_CAP,
              ],
            },
          } : {}),
        },
      },
    ],
    {
      updatePipeline: true,
      returnDocument: "after",
      projection: { points: 1, profileSubscription: 1 },
    },
  ).lean

