        stage: streamStage,
        priorResult: priorConsultation?.result || null,
        priorGenerationSource: priorConsultation?.generationSource || "",
        priorSnapshot: priorConsultation?.generationSnapshot || null,
        onSnapshot: snapshot => saveFusionGenerationSnapshot({ ...snapshot, userId: String(auth.userId) }),
        onReserved: () => claimFusionDeliveryLease({ userId: String(auth.userId), requestId: streamRequestId }),
        onRecoveryRequested: body?.resumeGeneration === true ? lease => requestFusionRecovery({ userId: String(auth.userId), requestId: streamRequestId, lease }) : undefined,
        onReleased: lease => releaseFusionDeliveryLease({ userId: String(auth.userId), requestId: streamRequestId, lease }),
        onAttempt: (groupId, lease, attemptOptions) => reserveFusionGroupAttempt({ userId: String(auth.userId), requestId: streamRequestId, groupId, lease, ...attemptOptions }),
        onStage: (stage) => writeFusionFortuneSse(writer, "stage", stage),

        // 저장을 배달보다 **먼저** 한다. 마지막 write 직전 연결이 끊겨도 결과는 남아
        // 재열람이 복구 경로가 된다(예전에는 그 순간 3만원짜리 결과가 그대로 사라졌다).
        onCheckpoint: async (delivery) => {
          const id = await persistFusionDelivery({ userId: String(auth.userId), input: priorConsultation?.generationSnapshot?.input || body, delivery });
          if (!id) throw new Error("FUSION_CHECKPOINT_SAVE_FAILED");
          await writeFusionFortuneSse(writer, "checkpoint", { result: delivery.result });
        },
        onDelivery: async (delivery) => {
          consultationId = await persistFusionDelivery({ userId: String(auth.userId), input: priorConsultation?.generationSnapshot?.input || body, delivery });
          const publicDelivery = { ...delivery };
          delete publicDelivery.lease;
          await writeFusionFortuneSse(writer, "result", { ...publicDelivery, consultationId });
        },
      });
      if (!result.ok) {
        await writeFusionFortuneSse(writer, "error", {
          error: result.error || FUSION_FORTUNE_ERROR_CODES.GENERATION_FAILED,
          reason: result.reason,
          resultId: result.resultId,
          message: result.message || "결과를 준비하지 못했어요. 같은 요청으로 다시 시도하면 추가 결제는 없습니다.",
          requestId: result.requestId || "",
          // 402(결제 필요)/503(판단 보류)를 클라이언트가 구분할 수 있어야 결제 게이트를 열지,
          // 재시도를 안내할지 고를 수 있다. SSE 는 HTTP 상태를 다시 줄 수 없어 본문에 싣는다.
          status: Number(result.status || 0) || undefined,
          pricing: result.pricing || undefined,
          retryable: result.retryable === true ? true : undefined,
          retryRequestId: result.retryRequestId || undefined,
          stage: Number(result.stage) || streamStage,
          // 어느 관문에서 죽었는지. 계약 위반 코드만 나가고 본문·개인정보는 실리지 않는다.
          issues: Array.isArray(result.issues) && result.issues.length ? result.issues.slice(0, 8) : undefined,
        });
        return;
      }
      await writeFusionFortuneSse(writer, "complete", {
        requestId: result.requestId,
        fusionStatus: result.fusionStatus,
        // 1단계면 partial — 클라이언트가 같은 requestId 로 stage 2 를 이어서 요청한다.
        stage: Number(result.stage) || streamStage,
        status: result.stageStatus || "completed",
        nextStage: result.nextStage,
        // 클라이언트가 저장된 결과의 ?cid= 딥링크를 남기는 데 쓴다.
        consultationId,
        qualityTier: result.qualityTier || undefined,
        qualityNotice: result.qualityNotice || undefined,
        automaticRetryAllowed: result.automaticRetryAllowed,
        pendingGroups: result.pendingGroups,
      });
    } catch (error) {
      await writeFusionFortuneSse(writer, "error", {
        ...(error?.code === "RESULT_STORAGE_UNAVAILABLE" ? { ...resultStorageFailurePayload(error), status: 503 } : {}),
        error: error?.code === "RESULT_STORAGE_UNAVAILABLE" ? error.code : FUSION_FORTUNE_ERROR_CODES.GENERATION_FAILED,
        message: "결과를 준비하지 못했어요. 같은 요청으로 다시 시도하면 추가 결제는 없습니다.",
      }).catch(() => {});
    } finally {
      // 하드 스톱이 먼저 닫았으면 settleStream 이 아무것도 하지 않는다(이중 종료 방지).
      await settleStream(null);
    }
  })

