        { "llmMeta.lockedAt": { $exists: false } },
        { "llmMeta.lockedAt": null },
        { "llmMeta.lockedAt": { $lt: staleBefore } },
      ],
    },
    {
      $inc: { "llmMeta.providerCallCount": 1, "llmMeta.waveCount": 1 },
      $set: {
        status: "generating",
        "llmMeta.lockedAt": new Date(now).toISOString(),
        "llmMeta.lockToken": lockToken,
        "llmMeta.providerCallLastAt": new Date(now).toISOString(),
      },
    },
    { new: true },
  ).lean

(async () => {
    await connectDb(env);
    const pricing = getPricing(normalized.input);
    const orderName = getConsultationOrderName(normalized.input);

    const existing = await LifeBookAiConsultation.findOne({ userId: clean(auth.userId), idempotencyKey }).lean();
    if (existing && clean(existing.inputHash) !== normalized.inputHash) return invalidInput(MESSAGES.invalidInput, 409);
    if (existing?.status === "completed") {
      logLifeBookAction("generate_reused", {
        route,
        requestId: idempotencyKey,
        userId: auth.userId,
        idempotencyKey,
        status: "completed",
        cacheHit: true,
        providerCallCount: Number(existing.llmMeta?.providerCallCount || 0),
      });
      return json(publicSession(existing));
    }
    if (existing?.status === "generating" && existing.llmMeta?.lockedAt
      && Date.now() - new Date(existing.llmMeta.lockedAt).getTime() < SECTION_LOCK_TTL_MS) {
      return json({ ...publicSession(existing), status: "generating", retryable: true }, { status: 202 });
    }
    if (existing?.status === "generation_failed") {
      logLifeBookAction("generate_blocked_duplicate", {
        route,
        requestId: idempotencyKey,
        userId: auth.userId,
        idempotencyKey,
        status: "generation_failed",
        cacheHit: true,
        duplicateBlocked: true,
        providerCallCount: Number(existing.llmMeta?.providerCallCount || 0),
        reason: clean(existing.generationError?.code || "GENERATION_ALREADY_FAILED", 80),
      }, "warn");
      return json({
        ...publicSession(existing),
        ok: false,
        reason: "GENERATION_ALREADY_FAILED",
        message: MESSAGES.llmFailed,
      }, { status: 409 });
    }

    logLifeBookAi("LLM Access Check Start", safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "passed", access: "checking", env }));
    const access = await resolveStartAccess({ request, env, auth, body, normalized, idempotencyKey });
    if (!access.ok) {
      if (access.reason === "LOGIN_REQUIRED") return loginRequired();
      if (access.reason === "INVALID_INPUT") return invalidInput(access.message, 409);
      return paymentVerifyFailed();
    }
    logLifeBookAi("LLM Access Check Success", safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "passed", access: access.accessType, env }));
    if (existing?.status === "delivery_pending") {
      const completed = await finishLifeBookDelivery({ request, env, auth, access, pending: existing, pricing, orderName });
      return json(publicSession(completed));
    }
    // 결제 증빙 1건 = 상담 1건. 이용권은 정산 때 이번 키로 차감하므로 claim 할 ID 가 없다.
    const evidenceClaim = await claimRequestBillingEvidence(env, { userId: clean(auth.userId), requestId: idempotencyKey, evidenceIds: [clean(access.claimEvidenceId, 160)], featureKey: clean(access.featureKey, 80) || getConsultationFeatureKey(normalized.input) });
    if (!evidenceClaim.ok) return json(evidenceClaimErrorBody(evidenceClaim), { status: evidenceClaim.status });

    let sajuResult = null;
    try {
      sajuResult = existing?.llmMeta?.factSnapshot || calculateLifeBookAiSaju(normalized.input.birthInfo);
    } catch (error) {
      if (isLifeFortuneInput(normalized.input)) {
        await restoreAccessBeforeGenerationFailure({
          request,
          env,
          auth,
          userId: auth.userId,
          access,
          idempotencyKey,
          sessionId: existing?.id || idempotencyKey,
          error,
          orderName,
          reason: MESSAGES.sajuCalculationFailed,
        });
        logLifeBookAi("LLM Error", safeLogPayload({
          route,
          requestId: idempotencyKey,
          body,
          normalized,
          validation: "saju_calculation_failed",
          access: access.accessType,
          env,
          error,
        }), "warn");
        return json({ ok: false, reason: "SAJU_CALCULATION_FAILED", message: MESSAGES.sajuCalculationFailed }, { status: 422 });
      }
      sajuResult = buildLimitedSajuResult(error, normalized.input.birthInfo);
      logLifeBookAi("LLM Error", safeLogPayload({
        route,
        requestId: idempotencyKey,
        body,
        normalized,
        validation: "saju_calculation_limited",
        access: access.accessType,
        env,
        error,
      }), "warn");
    }
    if (isLifeFortuneInput(normalized.input) && !hasRequiredLifeFortuneSaju(sajuResult, normalized.input.birthInfo)) {
      const error = Object.assign(new Error("life fortune saju result is incomplete"), { code: "SAJU_RESULT_INCOMPLETE" });
      await restoreAccessBeforeGenerationFailure({
        request,
        env,
        auth,
        userId: auth.userId,
        access,
        idempotencyKey,
        sessionId: existing?.id || idempotencyKey,
        error,
        orderName,
        reason: MESSAGES.sajuCalculationFailed,
      });
      logLifeBookAi("LLM Error", safeLogPayload({
        route,
        requestId: idempotencyKey,
        body,
        normalized,
        validation: "saju_result_incomplete",
        access: access.accessType,
        env,
        error,
      }), "warn");
      return json({ ok: false, reason: "SAJU_CALCULATION_FAILED", message: MESSAGES.sajuCalculationFailed }, { status: 422 });
    }

    const sessionId = existing?.id || `lbai_${clean(auth.userId).slice(-8)}_${Date.now().toString(36)}_${randomToken(8)}`;
    const now = new Date();
    const sectionPlan = buildSectionPlan(normalized.input);
    const seed = {
      id: sessionId,
      userId: clean(auth.userId),
      // 🔴 실제로 돈이 움직인 SKU. 구 SKU 로 결제된 총운 세션은 이 값으로 계속 정산해야
      //    apply/cancel/refund 가 원 차감 레코드와 같은 키로 대사된다.
      featureKey: access.featureKey || getConsultationFeatureKey(normalized.input),
      birthInfo: normalized.input.birthInfo,
      sajuResult,
      topic: normalized.input.topic,
      accessType: access.accessType,
      accessSource: access.accessSource || "",
      paymentId: clean(access.paymentId, 160),
      messages: [],
      title: "",
      keywords: [],
      idempotencyKey,
      inputHash: normalized.inputHash,
      status: "generating",
      generationError: null,
      llmMeta: {
        factSnapshot: sajuResult,
        resumeBody: { ...body, paymentId: clean(access.paymentId, 160) || body.paymentId, accessToken: undefined },
        providerCallCount: 0,
        providerCallLastAt: null,
        waveCount: 0,
        lockedAt: null,
        lockToken: "",
        plan: sectionPlan,
        sections: {},
        // 결제창이 사용자에게 보여준 금액. applyUsageOnce 가 현재가 대신 이 값을 쓰므로
        // SKU 가격이 바뀌어도 진행 중 세션이 안내와 다른 금액으로 차감되지 않는다.
        pricingSnapshot: {
          coinPrice: Number(pricing.coinPrice || 0),
          amountKRW: Number(pricing.amountKRW || 0),
          membershipCreditCost: Number(pricing.membershipCreditCost || 0),
        },
        input: {
          serviceType: normalized.input.serviceType,
          consultationType: normalized.input.consultationType,
          focusArea: normalized.input.focusArea,
          locale: normalized.input.locale,
        },
      },
    };

    if (!existing) {
      try {
        await LifeBookAiConsultation.create(seed);
      } catch (error) {
        if (error?.code === 11000) {
          const duplicate = await LifeBookAiConsultation.findOne({ userId: clean(auth.userId), idempotencyKey }).lean();
          logLifeBookAction("generate_reused", {
            route,
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            status: duplicate?.status || "generating",
            cacheHit: true,
            duplicateBlocked: true,
            providerCallCount: Number(duplicate?.llmMeta?.providerCallCount || 0),
            reason: "unique_index_collision",
          });
          if (duplicate?.status === "completed") return json(publicSession(duplicate));
          if (duplicate?.status === "generation_failed") {
            return json({
              ...publicSession(duplicate),
              ok: false,
              reason: "GENERATION_ALREADY_FAILED",
              message: MESSAGES.llmFailed,
            }, { status: 409 });
          }
          return json({ ok: true, sessionId: duplicate?.id || sessionId, status: "generating", message: `${orderName}을 완성하는 중입니다.` }, { status: 202 });
        }
        throw error;
      }
    }

    // 🔴 waitUntil 백그라운드 금지(요청 간 I/O 격리 + 예외 소실). 대신 한 요청 = 동시성 4 웨이브 하나만
    //    돌려 엣지 100초 안에서 끝내고, 남은 섹션이 있으면 202 + progress 를 돌려준다.
    //    클라(master-love-codex 의 runBatches 패턴)가 /generate 를 반복 호출해 진행을 이어받는다.
    try {
      const doc = await LifeBookAiConsultation.findOne({ id: sessionId, userId: clean(auth.userId) }).lean().catch(() => { throw resultStorageUnavailable(sessionId); });
      if (!doc) throw resultStorageUnavailable(sessionId);
      const plan = Array.isArray(doc?.llmMeta?.plan) && doc.llmMeta.plan.length ? doc.llmMeta.plan : sectionPlan;
      const storedSections = doc?.llmMeta?.sections && typeof doc.llmMeta.sections === "object" ? { ...doc.llmMeta.sections } : {};
      const waveCount = Number(doc?.llmMeta?.waveCount || 0);
      if (waveCount >= MAX_GENERATION_WAVES) {
        const error = Object.assign(new Error("Generation wave budget exhausted."), { code: "GENERATION_STALLED" });
        throw error;
      }

      const lock = await reserveProviderCallOnce({ userId: auth.userId, sessionId, idempotencyKey, route }).catch(error => {
        if (error?.code === "PROVIDER_DUPLICATE_BLOCKED") throw error;
        throw resultStorageUnavailable(sessionId);
      });
      const sections = lock.doc?.llmMeta?.sections || storedSections;
      let finished = false;
      let responsePayload = null;

      try {
        const pending = plan.filter((section) => {
          const stored = sections[section.id];
          if (!stored) return true;
          if (stored.repairKind === "length" && stored.ok) {
            stored.needsRepair = false;
            return false;
          }
          if (stored.needsRepair) return Number(stored.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS;
          if (!stored.ok) return Number(stored.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS;
          return false;
        }).slice(0, SECTION_BATCH_SIZE);

        const baseLogContext = {
          ...safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "passed", access: access.accessType, env }),
          ...buildProviderLogContext({
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            providerCallCount: lock.providerCallCount,
          }),
          featureKey: seed.featureKey,
          waveIndex: lock.waveCount,
        };

        if (pending.length) {
          const consultationType = isLifeFortuneInput(normalized.input) ? "lifeFortune" : "lifeBook";
          const results = await runWithConcurrency(pending, SECTION_CONCURRENCY, async (section) => {
            const stored = sections[section.id];
            const attempt = Number(stored?.attempts || 0) + 1;
            const lengthRepair = stored?.lengthRepair || (stored?.repairKind === "length" && stored?.ok);
            const reservedSection = { ...(stored || { id: section.id, kind: section.kind, ok: false }), attempts: attempt, lengthRepair };
            await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken, values: { [`llmMeta.sections.${section.id}`]: reservedSection } });
            // 재시도에서는 목표 분량을 올려 잡아 "또 짧게" 오는 것을 막는다.
            const boosted = stored?.needsRepair
              ? { ...section, targetChars: Math.round(section.targetChars * 1.25) }
              : section;
            const digest = buildSectionDigest(plan, sections, section.id);
            const prompt = buildSectionPrompt(normalized.input, pickSajuSlice(sajuResult, section.evidenceRefs), boosted, digest);
            const result = await generateSectionOnce(env, boosted, prompt, {
              consultationType,
              birthInfo: normalized.input.birthInfo,
              // 재시도는 캐시를 우회해야 같은 짧은 응답을 다시 받지 않는다.
              cache: attempt > 1 ? null : {
                store: createLlmCacheStore(env),
                deterministic: true,
                ttlSeconds: 30 * 24 * 60 * 60,
                keyExtra: `life-book-ai-v2-natal-v2-${consultationType}-${section.id}`,
              },
              logContext: { ...baseLogContext, sectionId: section.id, attempt },
            });
            const valid = row => row?.ok && lifeBookSectionValid(section, row.body, normalized.input)
              && !hasRepeatedReportPassage([...Object.entries(sections).filter(([id, value]) => id !== section.id && value.ok).map(([, value]) => value.body?.content || ""), row.body?.content || ""].join("\n"));
            const keepPrior = valid(stored) && (!valid(result) || sectionBodyChars(section, stored.body) >= sectionBodyChars(section, result.body));
            result.ok = Boolean(valid(result));
            const checkpoint = keepPrior
              ? { ...stored, attempts: attempt, lengthRepair, needsRepair: false }
              : { id: section.id, kind: section.kind, ok: result.ok, body: result.body, chars: result.chars, attempts: attempt, lengthRepair, provider: result.provider, model: result.model, error: result.error, needsRepair: false };
            await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken, values: { [`llmMeta.sections.${section.id}`]: checkpoint } });
            sections[section.id] = checkpoint;
            logLifeBookAction(result.ok ? "section_generate" : "section_retry", {
              route,
              requestId: idempotencyKey,
              userId: auth.userId,
              idempotencyKey,
              featureKey: seed.featureKey,
              status: result.ok ? "ok" : "failed",
              sectionId: section.id,
              waveIndex: lock.waveCount,
              attempt,
              promptChars: result.promptChars,
              responseChars: result.chars,
              durationMs: result.durationMs,
              parsed: result.parsed,
              providerCallCount: lock.providerCallCount,
              reason: result.error || "",
            }, result.ok ? "info" : "warn");
            return checkpoint;
          });

          for (const checkpoint of results) if (checkpoint) sections[checkpoint.id] = checkpoint;
        }

        // ── 조립 + 품질 게이트(정본 재사용). 결손은 책임 섹션에만 매핑한다.
        const missing = plan.filter((section) => !sections[section.id]?.ok
          && Number(sections[section.id]?.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS);
        let repairTargets = [];
        let assembled = null;
        let assembledText = "";
        let issues = [];

        if (!missing.length) {
          assembled = assembleReport(normalized.input, plan, sections);
          assembledText = JSON.stringify(assembled);
          issues = getLifeBookReportQualityIssues(assembledText, normalized.input, lifeBookLengthOptions(plan, sections));
          repairTargets = mapIssuesToSections(issues, plan, sections).targets
            .filter((id) => Number(sections[id]?.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS);
          for (const id of repairTargets) {
            if (sections[id]) {
              const section = plan.find(row => row.id === id);
              const lengthOnly = !issues.includes("total_content_too_short") && lifeBookSectionValid(section, sections[id].body, normalized.input)
                && sectionBodyChars(section, sections[id].body) < section.minChars;
              sections[id] = { ...sections[id], needsRepair: true, repairKind: lengthOnly ? "length" : "quality" };
            }
          }
          logLifeBookAction("quality_gate", {
            route,
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            featureKey: seed.featureKey,
            status: issues.length ? "issues" : "passed",
            waveIndex: lock.waveCount,
            responseChars: reportTotalContentChars(assembled),
            reason: issues.slice(0, 8).join(","),
          }, issues.length ? "warn" : "info");
        }

        const stillPending = plan.filter((section) => {
          const stored = sections[section.id];
          if (!stored) return true;
          if (stored.needsRepair || !stored.ok) return Number(stored.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS;
          return false;
        });
        const completedCount = plan.filter((section) => sections[section.id]?.ok).length;

        if (stillPending.length && (lock.waveCount < MAX_GENERATION_WAVES)) {
          const partial = await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken,
              values: {
                status: "partial",
                "llmMeta.sections": sections,
                // 부분 결과를 클라가 순차 공개할 수 있게 조립본을 미리 올려 둔다.
                "llmMeta.reportJson": assembled || assembleReport(normalized.input, plan, sections),
              },
          });
          logLifeBookAction("wave_complete", {
            route,
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            featureKey: seed.featureKey,
            status: "generating",
            waveIndex: lock.waveCount,
            persisted: true,
            reason: `pending:${stillPending.length}`,
          });
          responsePayload = json({
            ...publicSession(partial),
            ok: true,
            sessionId,
            status: "partial",
            progress: { completed: completedCount, total: plan.length },
            message: `${orderName}을 완성하는 중입니다.`,
          }, { status: 202, headers: { "Retry-After": "1" } });
        } else {
          finished = true;
        }

        if (finished) {
          const finalReport = assembled || assembleReport(normalized.input, plan, sections);
          const finalText = JSON.stringify(finalReport);
          const finalIssues = issues.length ? issues : getLifeBookReportQualityIssues(finalText, normalized.input, lifeBookLengthOptions(plan, sections));
          const totalChars = reportTotalContentChars(finalReport);
          const degraded = false;

          if (finalIssues.some(issue => issue !== "total_content_too_long")) {
            const error = new Error(`Life book result quality check failed: ${finalIssues.join(", ") || "empty_result"}`);
            error.code = isLifeFortuneInput(normalized.input) ? "LIFE_FORTUNE_REPORT_INVALID" : "LLM_QUALITY_CHECK_FAILED";
            throw error;
          }

          const title = extractTitle(finalText, normalized.input.birthInfo.name, normalized.input.consultationType);
          const keywords = extractKeywords(finalText, normalized.input.topic);
          const userMessage = normalized.input.consultationType === "lifeFortune"
            ? `상담 주제: ${normalized.input.topic}`
            : `리포트 강조 영역: ${normalized.input.topic}`;
          const usedProvider = clean(Object.values(sections).find((section) => section?.provider)?.provider || "gemini");
          const usedModel = clean(Object.values(sections).find((section) => section?.model)?.model);
          const delivery = await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken, values: {
                status: "delivery_pending",
                title,
                keywords,
                messages: [
                  { role: "user", content: userMessage, createdAt: now, idempotencyKey },
                  { role: "assistant", content: finalText, createdAt: new Date(), idempotencyKey },
                ],
                "llmMeta.provider": usedProvider,
                "llmMeta.model": usedModel,
                "llmMeta.reportJson": finalReport,
                "llmMeta.sections": sections,
                "llmMeta.degraded": degraded,
                "llmMeta.qualityIssues": finalIssues.slice(0, 20),
                "llmMeta.providerCallLastAt": new Date().toISOString(),
                "llmMeta.completedAt": new Date().toISOString(),
                generationError: null,
          } });
          const freshAccess = await resolveStartAccess({ request, env, auth, body, normalized, idempotencyKey }).catch(() => { throw resultStorageUnavailable(sessionId); });
          if (!freshAccess.ok) return paymentVerifyFailed();
          const completed = await finishLifeBookDelivery({ request, env, auth, access: freshAccess, pending: delivery, pricing, orderName });
          logLifeBookAction("wave_complete", {
            route,
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            featureKey: seed.featureKey,
            status: "completed",
            waveIndex: lock.waveCount,
            responseChars: totalChars,
            persisted: Boolean(completed),
            parsed: true,
            degraded,
          });
          logLifeBookAi("LLM Generate Success", safeLogPayload({
            route,
            requestId: idempotencyKey,
            body,
            normalized,
            validation: "passed",
            access: access.accessType,
            payment: "usage_applied",
            env,
            providerReason: usedProvider || usedModel,
          }));
          responsePayload = json(publicSession(completed));
        }
      } catch (error) {
        if (["RESULT_STORAGE_UNAVAILABLE", "RESULT_DELIVERY_PENDING"].includes(error?.code)) throw error;
        await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken, values: {
          status: "generation_failed", generationError: {
            code: clean(error?.code || "LLM_GENERATION_FAILED", 80),
            message: clean(error?.message || error, 500), at: new Date().toISOString(),
          },
        } });
        error.lifeBookFailureClaimed = true;
        throw error;
      } finally {
        await releaseSectionLock(sessionId, lock.lockToken);
      }
      return responsePayload;
    } catch (error) {
      if (["RESULT_STORAGE_UNAVAILABLE", "RESULT_DELIVERY_PENDING"].includes(error?.code)) return json({ ...resultStorageFailurePayload(error), reason: error.code, ...(error.code === "RESULT_DELIVERY_PENDING" ? { message: error.message } : {}) }, { status: 503 });
      if (clean(error?.code) === "PROVIDER_DUPLICATE_BLOCKED") {
        const duplicate = await LifeBookAiConsultation.findOne({ id: sessionId }).lean();
        if (duplicate?.status === "completed") return json(publicSession(duplicate));
        if (duplicate?.status === "generation_failed") {
          return json({
            ...publicSession(duplicate),
            ok: false,
            reason: "GENERATION_ALREADY_FAILED",
            message: MESSAGES.llmFailed,
          }, { status: 409 });
        }
        return json({
          ok: false,
          retryable: true,
          reason: "GENERATION_IN_PROGRESS",
          sessionId,
          status: "generating",
          message: `${orderName}을 완성하는 중입니다.`,
        }, { status: 409, headers: { "Retry-After": "4" } });
      }
      const failedOwner = error.lifeBookFailureClaimed || await LifeBookAiConsultation.findOneAndUpdate(
        { id: sessionId, userId: clean(auth.userId), status: { $in: ["generating", "partial"] }, "llmMeta.lockedAt": null, "llmMeta.waveCount": { $gte: MAX_GENERATION_WAVES } },
        { $set: { status: "generation_failed", generationError: {
          code: clean(error?.code || "LLM_GENERATION_FAILED", 80),
          message: clean(error?.message || error, 500), at: new Date().toISOString(),
        } } }, { new: true },
      ).lean().catch(() => null);
      if (!failedOwner) return json(resultStorageFailurePayload(resultStorageUnavailable(sessionId)), { status: 503 });
      const restored = await restoreAccessBeforeGenerationFailure({
        request,
        env,
        auth,
        userId: auth.userId,
        access,
        idempotencyKey,
        sessionId,
        error,
        orderName,
      });
      logLifeBookAi("Refund Or Restore", safeLogPayload({
        route,
        requestId: idempotencyKey,
        body,
        normalized,
        validation: "passed",
        access: access.accessType,
        payment: restored ? "restored_or_canceled" : "no_deferred_usage_to_restore",
        env,
        error,
      }), restored ? "info" : "warn");
      logLifeBookAi("LLM Error", safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "passed", access: access.accessType, env, error }), "error");
      if (clean(error?.code) === "DEFERRED_USAGE_APPLY_FAILED") return paymentVerifyFailed();
      return json({ ok: false, reason: "LLM_ERROR", message: MESSAGES.llmFailed, refunded: Boolean(restored) }, { status: 503 });
    }
  })().catch((error) => {
    if (["RESULT_STORAGE_UNAVAILABLE", "RESULT_DELIVERY_PENDING"].includes(error?.code)) return json({ ...resultStorageFailurePayload(error), reason: error.code, ...(error.code === "RESULT_DELIVERY_PENDING" ? { message: error.message } : {}) }, { status: 503 });
    logLifeBookAi("LLM Error", safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "server_error", env, error }), "error");
    return serverError();
  }).finally

(async () => {
    await connectDb(env);
    const pricing = getPricing(normalized.input);
    const orderName = getConsultationOrderName(normalized.input);

    const existing = await LifeBookAiConsultation.findOne({ userId: clean(auth.userId), idempotencyKey }).lean();
    if (existing && clean(existing.inputHash) !== normalized.inputHash) return invalidInput(MESSAGES.invalidInput, 409);
    if (existing?.status === "completed") {
      logLifeBookAction("generate_reused", {
        route,
        requestId: idempotencyKey,
        userId: auth.userId,
        idempotencyKey,
        status: "completed",
        cacheHit: true,
        providerCallCount: Number(existing.llmMeta?.providerCallCount || 0),
      });
      return json(publicSession(existing));
    }
    if (existing?.status === "generating" && existing.llmMeta?.lockedAt
      && Date.now() - new Date(existing.llmMeta.lockedAt).getTime() < SECTION_LOCK_TTL_MS) {
      return json({ ...publicSession(existing), status: "generating", retryable: true }, { status: 202 });
    }
    if (existing?.status === "generation_failed") {
      logLifeBookAction("generate_blocked_duplicate", {
        route,
        requestId: idempotencyKey,
        userId: auth.userId,
        idempotencyKey,
        status: "generation_failed",
        cacheHit: true,
        duplicateBlocked: true,
        providerCallCount: Number(existing.llmMeta?.providerCallCount || 0),
        reason: clean(existing.generationError?.code || "GENERATION_ALREADY_FAILED", 80),
      }, "warn");
      return json({
        ...publicSession(existing),
        ok: false,
        reason: "GENERATION_ALREADY_FAILED",
        message: MESSAGES.llmFailed,
      }, { status: 409 });
    }

    logLifeBookAi("LLM Access Check Start", safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "passed", access: "checking", env }));
    const access = await resolveStartAccess({ request, env, auth, body, normalized, idempotencyKey });
    if (!access.ok) {
      if (access.reason === "LOGIN_REQUIRED") return loginRequired();
      if (access.reason === "INVALID_INPUT") return invalidInput(access.message, 409);
      return paymentVerifyFailed();
    }
    logLifeBookAi("LLM Access Check Success", safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "passed", access: access.accessType, env }));
    if (existing?.status === "delivery_pending") {
      const completed = await finishLifeBookDelivery({ request, env, auth, access, pending: existing, pricing, orderName });
      return json(publicSession(completed));
    }
    // 결제 증빙 1건 = 상담 1건. 이용권은 정산 때 이번 키로 차감하므로 claim 할 ID 가 없다.
    const evidenceClaim = await claimRequestBillingEvidence(env, { userId: clean(auth.userId), requestId: idempotencyKey, evidenceIds: [clean(access.claimEvidenceId, 160)], featureKey: clean(access.featureKey, 80) || getConsultationFeatureKey(normalized.input) });
    if (!evidenceClaim.ok) return json(evidenceClaimErrorBody(evidenceClaim), { status: evidenceClaim.status });

    let sajuResult = null;
    try {
      sajuResult = existing?.llmMeta?.factSnapshot || calculateLifeBookAiSaju(normalized.input.birthInfo);
    } catch (error) {
      if (isLifeFortuneInput(normalized.input)) {
        await restoreAccessBeforeGenerationFailure({
          request,
          env,
          auth,
          userId: auth.userId,
          access,
          idempotencyKey,
          sessionId: existing?.id || idempotencyKey,
          error,
          orderName,
          reason: MESSAGES.sajuCalculationFailed,
        });
        logLifeBookAi("LLM Error", safeLogPayload({
          route,
          requestId: idempotencyKey,
          body,
          normalized,
          validation: "saju_calculation_failed",
          access: access.accessType,
          env,
          error,
        }), "warn");
        return json({ ok: false, reason: "SAJU_CALCULATION_FAILED", message: MESSAGES.sajuCalculationFailed }, { status: 422 });
      }
      sajuResult = buildLimitedSajuResult(error, normalized.input.birthInfo);
      logLifeBookAi("LLM Error", safeLogPayload({
        route,
        requestId: idempotencyKey,
        body,
        normalized,
        validation: "saju_calculation_limited",
        access: access.accessType,
        env,
        error,
      }), "warn");
    }
    if (isLifeFortuneInput(normalized.input) && !hasRequiredLifeFortuneSaju(sajuResult, normalized.input.birthInfo)) {
      const error = Object.assign(new Error("life fortune saju result is incomplete"), { code: "SAJU_RESULT_INCOMPLETE" });
      await restoreAccessBeforeGenerationFailure({
        request,
        env,
        auth,
        userId: auth.userId,
        access,
        idempotencyKey,
        sessionId: existing?.id || idempotencyKey,
        error,
        orderName,
        reason: MESSAGES.sajuCalculationFailed,
      });
      logLifeBookAi("LLM Error", safeLogPayload({
        route,
        requestId: idempotencyKey,
        body,
        normalized,
        validation: "saju_result_incomplete",
        access: access.accessType,
        env,
        error,
      }), "warn");
      return json({ ok: false, reason: "SAJU_CALCULATION_FAILED", message: MESSAGES.sajuCalculationFailed }, { status: 422 });
    }

    const sessionId = existing?.id || `lbai_${clean(auth.userId).slice(-8)}_${Date.now().toString(36)}_${randomToken(8)}`;
    const now = new Date();
    const sectionPlan = buildSectionPlan(normalized.input);
    const seed = {
      id: sessionId,
      userId: clean(auth.userId),
      // 🔴 실제로 돈이 움직인 SKU. 구 SKU 로 결제된 총운 세션은 이 값으로 계속 정산해야
      //    apply/cancel/refund 가 원 차감 레코드와 같은 키로 대사된다.
      featureKey: access.featureKey || getConsultationFeatureKey(normalized.input),
      birthInfo: normalized.input.birthInfo,
      sajuResult,
      topic: normalized.input.topic,
      accessType: access.accessType,
      accessSource: access.accessSource || "",
      paymentId: clean(access.paymentId, 160),
      messages: [],
      title: "",
      keywords: [],
      idempotencyKey,
      inputHash: normalized.inputHash,
      status: "generating",
      generationError: null,
      llmMeta: {
        factSnapshot: sajuResult,
        resumeBody: { ...body, paymentId: clean(access.paymentId, 160) || body.paymentId, accessToken: undefined },
        providerCallCount: 0,
        providerCallLastAt: null,
        waveCount: 0,
        lockedAt: null,
        lockToken: "",
        plan: sectionPlan,
        sections: {},
        // 결제창이 사용자에게 보여준 금액. applyUsageOnce 가 현재가 대신 이 값을 쓰므로
        // SKU 가격이 바뀌어도 진행 중 세션이 안내와 다른 금액으로 차감되지 않는다.
        pricingSnapshot: {
          coinPrice: Number(pricing.coinPrice || 0),
          amountKRW: Number(pricing.amountKRW || 0),
          membershipCreditCost: Number(pricing.membershipCreditCost || 0),
        },
        input: {
          serviceType: normalized.input.serviceType,
          consultationType: normalized.input.consultationType,
          focusArea: normalized.input.focusArea,
          locale: normalized.input.locale,
        },
      },
    };

    if (!existing) {
      try {
        await LifeBookAiConsultation.create(seed);
      } catch (error) {
        if (error?.code === 11000) {
          const duplicate = await LifeBookAiConsultation.findOne({ userId: clean(auth.userId), idempotencyKey }).lean();
          logLifeBookAction("generate_reused", {
            route,
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            status: duplicate?.status || "generating",
            cacheHit: true,
            duplicateBlocked: true,
            providerCallCount: Number(duplicate?.llmMeta?.providerCallCount || 0),
            reason: "unique_index_collision",
          });
          if (duplicate?.status === "completed") return json(publicSession(duplicate));
          if (duplicate?.status === "generation_failed") {
            return json({
              ...publicSession(duplicate),
              ok: false,
              reason: "GENERATION_ALREADY_FAILED",
              message: MESSAGES.llmFailed,
            }, { status: 409 });
          }
          return json({ ok: true, sessionId: duplicate?.id || sessionId, status: "generating", message: `${orderName}을 완성하는 중입니다.` }, { status: 202 });
        }
        throw error;
      }
    }

    // 🔴 waitUntil 백그라운드 금지(요청 간 I/O 격리 + 예외 소실). 대신 한 요청 = 동시성 4 웨이브 하나만
    //    돌려 엣지 100초 안에서 끝내고, 남은 섹션이 있으면 202 + progress 를 돌려준다.
    //    클라(master-love-codex 의 runBatches 패턴)가 /generate 를 반복 호출해 진행을 이어받는다.
    try {
      const doc = await LifeBookAiConsultation.findOne({ id: sessionId, userId: clean(auth.userId) }).lean().catch(() => { throw resultStorageUnavailable(sessionId); });
      if (!doc) throw resultStorageUnavailable(sessionId);
      const plan = Array.isArray(doc?.llmMeta?.plan) && doc.llmMeta.plan.length ? doc.llmMeta.plan : sectionPlan;
      const storedSections = doc?.llmMeta?.sections && typeof doc.llmMeta.sections === "object" ? { ...doc.llmMeta.sections } : {};
      const waveCount = Number(doc?.llmMeta?.waveCount || 0);
      if (waveCount >= MAX_GENERATION_WAVES) {
        const error = Object.assign(new Error("Generation wave budget exhausted."), { code: "GENERATION_STALLED" });
        throw error;
      }

      const lock = await reserveProviderCallOnce({ userId: auth.userId, sessionId, idempotencyKey, route }).catch(error => {
        if (error?.code === "PROVIDER_DUPLICATE_BLOCKED") throw error;
        throw resultStorageUnavailable(sessionId);
      });
      const sections = lock.doc?.llmMeta?.sections || storedSections;
      let finished = false;
      let responsePayload = null;

      try {
        const pending = plan.filter((section) => {
          const stored = sections[section.id];
          if (!stored) return true;
          if (stored.repairKind === "length" && stored.ok) {
            stored.needsRepair = false;
            return false;
          }
          if (stored.needsRepair) return Number(stored.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS;
          if (!stored.ok) return Number(stored.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS;
          return false;
        }).slice(0, SECTION_BATCH_SIZE);

        const baseLogContext = {
          ...safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "passed", access: access.accessType, env }),
          ...buildProviderLogContext({
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            providerCallCount: lock.providerCallCount,
          }),
          featureKey: seed.featureKey,
          waveIndex: lock.waveCount,
        };

        if (pending.length) {
          const consultationType = isLifeFortuneInput(normalized.input) ? "lifeFortune" : "lifeBook";
          const results = await runWithConcurrency(pending, SECTION_CONCURRENCY, async (section) => {
            const stored = sections[section.id];
            const attempt = Number(stored?.attempts || 0) + 1;
            const lengthRepair = stored?.lengthRepair || (stored?.repairKind === "length" && stored?.ok);
            const reservedSection = { ...(stored || { id: section.id, kind: section.kind, ok: false }), attempts: attempt, lengthRepair };
            await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken, values: { [`llmMeta.sections.${section.id}`]: reservedSection } });
            // 재시도에서는 목표 분량을 올려 잡아 "또 짧게" 오는 것을 막는다.
            const boosted = stored?.needsRepair
              ? { ...section, targetChars: Math.round(section.targetChars * 1.25) }
              : section;
            const digest = buildSectionDigest(plan, sections, section.id);
            const prompt = buildSectionPrompt(normalized.input, pickSajuSlice(sajuResult, section.evidenceRefs), boosted, digest);
            const result = await generateSectionOnce(env, boosted, prompt, {
              consultationType,
              birthInfo: normalized.input.birthInfo,
              // 재시도는 캐시를 우회해야 같은 짧은 응답을 다시 받지 않는다.
              cache: attempt > 1 ? null : {
                store: createLlmCacheStore(env),
                deterministic: true,
                ttlSeconds: 30 * 24 * 60 * 60,
                keyExtra: `life-book-ai-v2-natal-v2-${consultationType}-${section.id}`,
              },
              logContext: { ...baseLogContext, sectionId: section.id, attempt },
            });
            const valid = row => row?.ok && lifeBookSectionValid(section, row.body, normalized.input)
              && !hasRepeatedReportPassage([...Object.entries(sections).filter(([id, value]) => id !== section.id && value.ok).map(([, value]) => value.body?.content || ""), row.body?.content || ""].join("\n"));
            const keepPrior = valid(stored) && (!valid(result) || sectionBodyChars(section, stored.body) >= sectionBodyChars(section, result.body));
            result.ok = Boolean(valid(result));
            const checkpoint = keepPrior
              ? { ...stored, attempts: attempt, lengthRepair, needsRepair: false }
              : { id: section.id, kind: section.kind, ok: result.ok, body: result.body, chars: result.chars, attempts: attempt, lengthRepair, provider: result.provider, model: result.model, error: result.error, needsRepair: false };
            await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken, values: { [`llmMeta.sections.${section.id}`]: checkpoint } });
            sections[section.id] = checkpoint;
            logLifeBookAction(result.ok ? "section_generate" : "section_retry", {
              route,
              requestId: idempotencyKey,
              userId: auth.userId,
              idempotencyKey,
              featureKey: seed.featureKey,
              status: result.ok ? "ok" : "failed",
              sectionId: section.id,
              waveIndex: lock.waveCount,
              attempt,
              promptChars: result.promptChars,
              responseChars: result.chars,
              durationMs: result.durationMs,
              parsed: result.parsed,
              providerCallCount: lock.providerCallCount,
              reason: result.error || "",
            }, result.ok ? "info" : "warn");
            return checkpoint;
          });

          for (const checkpoint of results) if (checkpoint) sections[checkpoint.id] = checkpoint;
        }

        // ── 조립 + 품질 게이트(정본 재사용). 결손은 책임 섹션에만 매핑한다.
        const missing = plan.filter((section) => !sections[section.id]?.ok
          && Number(sections[section.id]?.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS);
        let repairTargets = [];
        let assembled = null;
        let assembledText = "";
        let issues = [];

        if (!missing.length) {
          assembled = assembleReport(normalized.input, plan, sections);
          assembledText = JSON.stringify(assembled);
          issues = getLifeBookReportQualityIssues(assembledText, normalized.input, lifeBookLengthOptions(plan, sections));
          repairTargets = mapIssuesToSections(issues, plan, sections).targets
            .filter((id) => Number(sections[id]?.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS);
          for (const id of repairTargets) {
            if (sections[id]) {
              const section = plan.find(row => row.id === id);
              const lengthOnly = !issues.includes("total_content_too_short") && lifeBookSectionValid(section, sections[id].body, normalized.input)
                && sectionBodyChars(section, sections[id].body) < section.minChars;
              sections[id] = { ...sections[id], needsRepair: true, repairKind: lengthOnly ? "length" : "quality" };
            }
          }
          logLifeBookAction("quality_gate", {
            route,
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            featureKey: seed.featureKey,
            status: issues.length ? "issues" : "passed",
            waveIndex: lock.waveCount,
            responseChars: reportTotalContentChars(assembled),
            reason: issues.slice(0, 8).join(","),
          }, issues.length ? "warn" : "info");
        }

        const stillPending = plan.filter((section) => {
          const stored = sections[section.id];
          if (!stored) return true;
          if (stored.needsRepair || !stored.ok) return Number(stored.attempts || 0) < LIFE_BOOK_MAX_SECTION_ATTEMPTS;
          return false;
        });
        const completedCount = plan.filter((section) => sections[section.id]?.ok).length;

        if (stillPending.length && (lock.waveCount < MAX_GENERATION_WAVES)) {
          const partial = await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken,
              values: {
                status: "partial",
                "llmMeta.sections": sections,
                // 부분 결과를 클라가 순차 공개할 수 있게 조립본을 미리 올려 둔다.
                "llmMeta.reportJson": assembled || assembleReport(normalized.input, plan, sections),
              },
          });
          logLifeBookAction("wave_complete", {
            route,
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            featureKey: seed.featureKey,
            status: "generating",
            waveIndex: lock.waveCount,
            persisted: true,
            reason: `pending:${stillPending.length}`,
          });
          responsePayload = json({
            ...publicSession(partial),
            ok: true,
            sessionId,
            status: "partial",
            progress: { completed: completedCount, total: plan.length },
            message: `${orderName}을 완성하는 중입니다.`,
          }, { status: 202, headers: { "Retry-After": "1" } });
        } else {
          finished = true;
        }

        if (finished) {
          const finalReport = assembled || assembleReport(normalized.input, plan, sections);
          const finalText = JSON.stringify(finalReport);
          const finalIssues = issues.length ? issues : getLifeBookReportQualityIssues(finalText, normalized.input, lifeBookLengthOptions(plan, sections));
          const totalChars = reportTotalContentChars(finalReport);
          const degraded = false;

          if (finalIssues.some(issue => issue !== "total_content_too_long")) {
            const error = new Error(`Life book result quality check failed: ${finalIssues.join(", ") || "empty_result"}`);
            error.code = isLifeFortuneInput(normalized.input) ? "LIFE_FORTUNE_REPORT_INVALID" : "LLM_QUALITY_CHECK_FAILED";
            throw error;
          }

          const title = extractTitle(finalText, normalized.input.birthInfo.name, normalized.input.consultationType);
          const keywords = extractKeywords(finalText, normalized.input.topic);
          const userMessage = normalized.input.consultationType === "lifeFortune"
            ? `상담 주제: ${normalized.input.topic}`
            : `리포트 강조 영역: ${normalized.input.topic}`;
          const usedProvider = clean(Object.values(sections).find((section) => section?.provider)?.provider || "gemini");
          const usedModel = clean(Object.values(sections).find((section) => section?.model)?.model);
          const delivery = await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken, values: {
                status: "delivery_pending",
                title,
                keywords,
                messages: [
                  { role: "user", content: userMessage, createdAt: now, idempotencyKey },
                  { role: "assistant", content: finalText, createdAt: new Date(), idempotencyKey },
                ],
                "llmMeta.provider": usedProvider,
                "llmMeta.model": usedModel,
                "llmMeta.reportJson": finalReport,
                "llmMeta.sections": sections,
                "llmMeta.degraded": degraded,
                "llmMeta.qualityIssues": finalIssues.slice(0, 20),
                "llmMeta.providerCallLastAt": new Date().toISOString(),
                "llmMeta.completedAt": new Date().toISOString(),
                generationError: null,
          } });
          const freshAccess = await resolveStartAccess({ request, env, auth, body, normalized, idempotencyKey }).catch(() => { throw resultStorageUnavailable(sessionId); });
          if (!freshAccess.ok) return paymentVerifyFailed();
          const completed = await finishLifeBookDelivery({ request, env, auth, access: freshAccess, pending: delivery, pricing, orderName });
          logLifeBookAction("wave_complete", {
            route,
            requestId: idempotencyKey,
            userId: auth.userId,
            idempotencyKey,
            featureKey: seed.featureKey,
            status: "completed",
            waveIndex: lock.waveCount,
            responseChars: totalChars,
            persisted: Boolean(completed),
            parsed: true,
            degraded,
          });
          logLifeBookAi("LLM Generate Success", safeLogPayload({
            route,
            requestId: idempotencyKey,
            body,
            normalized,
            validation: "passed",
            access: access.accessType,
            payment: "usage_applied",
            env,
            providerReason: usedProvider || usedModel,
          }));
          responsePayload = json(publicSession(completed));
        }
      } catch (error) {
        if (["RESULT_STORAGE_UNAVAILABLE", "RESULT_DELIVERY_PENDING"].includes(error?.code)) throw error;
        await saveLifeBookState({ userId: auth.userId, id: sessionId, lockToken: lock.lockToken, values: {
          status: "generation_failed", generationError: {
            code: clean(error?.code || "LLM_GENERATION_FAILED", 80),
            message: clean(error?.message || error, 500), at: new Date().toISOString(),
          },
        } });
        error.lifeBookFailureClaimed = true;
        throw error;
      } finally {
        await releaseSectionLock(sessionId, lock.lockToken);
      }
      return responsePayload;
    } catch (error) {
      if (["RESULT_STORAGE_UNAVAILABLE", "RESULT_DELIVERY_PENDING"].includes(error?.code)) return json({ ...resultStorageFailurePayload(error), reason: error.code, ...(error.code === "RESULT_DELIVERY_PENDING" ? { message: error.message } : {}) }, { status: 503 });
      if (clean(error?.code) === "PROVIDER_DUPLICATE_BLOCKED") {
        const duplicate = await LifeBookAiConsultation.findOne({ id: sessionId }).lean();
        if (duplicate?.status === "completed") return json(publicSession(duplicate));
        if (duplicate?.status === "generation_failed") {
          return json({
            ...publicSession(duplicate),
            ok: false,
            reason: "GENERATION_ALREADY_FAILED",
            message: MESSAGES.llmFailed,
          }, { status: 409 });
        }
        return json({
          ok: false,
          retryable: true,
          reason: "GENERATION_IN_PROGRESS",
          sessionId,
          status: "generating",
          message: `${orderName}을 완성하는 중입니다.`,
        }, { status: 409, headers: { "Retry-After": "4" } });
      }
      const failedOwner = error.lifeBookFailureClaimed || await LifeBookAiConsultation.findOneAndUpdate(
        { id: sessionId, userId: clean(auth.userId), status: { $in: ["generating", "partial"] }, "llmMeta.lockedAt": null, "llmMeta.waveCount": { $gte: MAX_GENERATION_WAVES } },
        { $set: { status: "generation_failed", generationError: {
          code: clean(error?.code || "LLM_GENERATION_FAILED", 80),
          message: clean(error?.message || error, 500), at: new Date().toISOString(),
        } } }, { new: true },
      ).lean().catch(() => null);
      if (!failedOwner) return json(resultStorageFailurePayload(resultStorageUnavailable(sessionId)), { status: 503 });
      const restored = await restoreAccessBeforeGenerationFailure({
        request,
        env,
        auth,
        userId: auth.userId,
        access,
        idempotencyKey,
        sessionId,
        error,
        orderName,
      });
      logLifeBookAi("Refund Or Restore", safeLogPayload({
        route,
        requestId: idempotencyKey,
        body,
        normalized,
        validation: "passed",
        access: access.accessType,
        payment: restored ? "restored_or_canceled" : "no_deferred_usage_to_restore",
        env,
        error,
      }), restored ? "info" : "warn");
      logLifeBookAi("LLM Error", safeLogPayload({ route, requestId: idempotencyKey, body, normalized, validation: "passed", access: access.accessType, env, error }), "error");
