    const sessionId = existing?.id || `lbai_${clean(auth.userId).slice(-8)}_${Date.now().toString(36)}_${randomToken(8)}`;
    const now = new Date();
    const sectionPlan = buildSectionPlan(normalized.input);
    const seed = {
